  function officialPrayerLines(text) {
    return String(text || '').split(/\n+/).map(value => value.trim()).filter(Boolean).map(value => {
      const spoken = value.match(/^(主祭|信友|全體)\s*[:：]\s*(.*)$/u);
      if (spoken) return z(spoken[1], spoken[2]);
      if (/^(?:感恩經第|紀念|節日專用|呼求|成聖|祝聖後|第一式|第二式|第三式|第四式|主祭伸手|主祭覆手|主祭俯身|主祭右手|聖三頌|頌謝詞|特殊禮儀日|主日|聖誕|主顯|復活|耶穌升天|五旬|亡者彌撒|追思已亡|或|然後|－下接|-下接|\()/u.test(value)) return rubric(value);
      return z('', value);
    });
  }

