  function dailyPdfUrl(ymd) {
    const entries = dailyManifest[String(ymd || '')] || [];
    const selected = entries[0];
    return selected
      ? `https://drive.usercontent.google.com/download?id=${encodeURIComponent(selected.id)}&export=download&confirm=t`
      : '';
  }

